"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Новы выгляд руды: жылы — свецяцца смарагдавыя гранёныя крышталі на чорным базальце, іскры і зялёная смуга; Экстрактар — шасцігранны пастамент, сотавы купал і краты вежа з зялёным агнём-маяком (паласа і вымпел — колер каманды)",
"New in v6.1":"Новае ў v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Свой клас як у Battlefield (U, лічбы пасля гібелі): вы адраджаецеся ім, калі ён даступны",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Тэхніка ад першай асобы (V — звонку/з кабіны); лёгкае аўтапрыцэльванне — у Наладах",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"З ядра цяпер лёгка выбрацца: Прабел — да шахты, B — капсула на паверхню; эфекты здольнасцей скідаюцца пры гібелі",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Бясконцая пракачка: генералы і Маршал ★, узроўні кар'еры, майстэрства зброі і абвесы, медалі, штодзённыя кантракты — экран «Кар'ера»",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Стратэгія: плаўны зум коліцам, значкі і подпісы над юнітамі (Alt — усе), панэль «Войскі / Будынкі» злева",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"ПКМ — ісці і ваяваць па дарозе, 2× ПКМ — марш са стральбой на хаду; рэдкія загады — у «Іншыя загады ▾»; кнопкі не дублююцца",
"New in v6":"Новае ў v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Страляніна як у шутэрах: імгненныя кулі, аўтамат 720 стрэлаў/хв, кулямёт, аддача, прыцэл на ПКМ, магазіны і перазарадка R, адзнакі трапленняў",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Цяжэйшая гравітацыя, спраўны джэтпак, рыўок на Z або 2× джэтпак у паветры; пры пераляце ў іншага байца зброя больш не ляціць",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Інжынеры: вылучы інжынера, выберы будынак, пастаў чарцёж; Экстрактары на рудных жылах; клік па «РУДА» — адкуль даход і як яго паскорыць",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Шэрыя кнопкі можна націснуць — пакажам прычыну і кнопку-рашэнне; буйныя кнопкі, паласа «У працы», «▶ Кіраваць», Tab — адна клавіша",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Камера стратэгіі без рыўкоў і перавартаў, зум да курсора, міні-карту можна цягаць",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Новая тэхніка: рэйдар «Шакал», РСАВ «Град» (ракеты з саманаводкай), мінамёт «Молат»; у Раі «Аса», «Вулей», «Трэбушэт»",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Стратэг не мяняе загады і не спаміць голасам; баі побач з табой; B — пераздзяленне, Shift+B — у гушчу бою; компас, H — якая мэта",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Свабода дзеянняў (K) і «дзейнічаю адзін» (J), F2 — прэсеты; Esc — паўза і назад; захаванні: слоты, экспарт і імпарт файла",
"New in v5.3":"Новае ў v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Палёт: цяжар удалечыні ад метэарыта мацнейшы, C у паветры — тармаз, цяга рулюе рэзчэй; больш не «завісаеш» у парталі",
"New in v5":"Новае ў v5",
"Endless war by default and battle scale: normal, large, epic":"Бясконцы бой па змаўчанні і маштаб баёў: звычайны, буйны, эпічны",
