"Squadmates with callsigns: portraits, health and live chatter":"Атрад з пазыўнымі: партрэты, здароўе і жывыя перагаворы",
"Fog of war in strategy, friends and foes outlined differently":"Туман вайны ў стратэгіі, свае і ворагі падсвечаны па-рознаму",
"Camera fly-over when switching, portal aurora instead of rings":"Пралёт камеры пры пераключэнні, ззянне партала замест колцаў",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Пабочныя задачы, кароткі шлях праз неба, модулі першай экспедыцыі з прыпасамі, крышталі, лёд у кратарах, пылавыя буры",
