"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"Граната: трымай G — убачыш дугу і круг выбуху; вядзі пальцам па кнопцы — вугал; адпусці — кідок.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Граната: трымай {0} — дуга і круг выбуху, адпусці — кідок. Далёкасць — вуглом погляду, кола — сіла, ПКМ — знізу.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Гранаты: трымай G — дуга палёту, кропка і круг выбуху, дыстанцыя; адпусці — кідок. Далёкасць — вуглом погляду, кола — сіла, ПКМ — знізу",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Граната адскоквае і коціцца па схіле, запал 2.5 с; 2 гранаты, аднаўленне 9 с; значок-папярэджанне пра варожую гранату побач",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"Граната: трымаць — дуга і кропка выбуху, адпусціць — кідок · форсаж танка",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — трымай: відаць дуга і круг выбуху, адпусці — кідок. Запал 2.5 с, 2 гранаты.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Граната ({0}): трымай — дуга палёту, кропка і круг выбуху, дыстанцыя; адпусці — кідок; кароткае націсканне — адразу кідок. Далёкасць — вуглом погляду, кола — сіла, ПКМ — знізу. Тэлефон: трымай G і вядзі пальцам.",
