"🛠 Developer mode: everything unlocked, endless ore. Arsenal — F8 or the \"🛠 Arsenal\" button.":"🛠 Рэжым распрацоўшчыка: усё адкрыта, руда без канца. Арсенал — F8 або кнопка «🛠 Арсенал».",
"Developer mode off (the match stays flagged — career is not saved)":"Рэжым распрацоўшчыка выключаны (матч застаецца пазначаным — кар'ера не запісваецца)",
"Battle saves are disabled in developer mode":"У рэжыме распрацоўшчыка захаванні бою адключаны",
