"Voice of hints & curator":"Голас падказак і наставіка",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Тэлефон: тры рэжымы джойсцікаў. Толькі левы — «аўта» (моцны магніт, але кулі слабейшыя). Толькі правы — прыцэліванне ўключаецца само, магніт мацнейшы, дакладнасць вышэйшая. Абодва адразу — без прыцэліўвання, магніт і дакладнасць меншыя. Кнопка 👁 справа — схаваць/вярнуць інтэрфейс.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Тэлефон: стратэгія спрошчана — толькі інжынер і будынкі. Злева карткі (інжынер, штаб, казарма…): тап — камера да яго, ніжэй адразу што будаваць/вырабляць. «У бой» — злева зверху. Армія ваюе сама. Поўная стратэгія — Налады → Тэлефон.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Захоп — дзве галачкі: «Атрады» і «Тэхніка» (на тэлефоне тэхніка па змаўчанні выключана — яе вядзе ШІ). Калі тэхніка выключана, E (на тэлефоне — кнопка справа) побач са сваёй машынай — сесці за яе гармату: машына едзе сама, ты страляеш. Стары «свой парадак класаў» — у «Пашыраных». Пры захопе юніт адказвае па рацыі.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Разумныя падказкі: базавыя самі гаснуць пасля 2-га запуску, але гульня падкажа функцыю, якой ты так і не карыстаешся. Галачкі: базавыя / пашыраныя / рэдкія, асобна — голас падказак і наставіка.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Рэфлекс зараджаецца ад забойстваў (серыя — мацней). Напарнікі адсталі ці загінулі — стратэг дэсантуе да цябе новых (даражэй за звычайнае папаўненне). Графіка і гук v7.2gfx улітыя: выбухі клубамі, дым, абломкі, акустыка шахт і кратараў. Дата зборкі — сапраўдная.",
