"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Кар'ера і захаванні не мяняюцца. У баі тое ж меню — кнопка «🛠 Меню» ўверсе справа{0}.",
"New developer match":"Новы матч распрацоўшчыка",
"all unlocked, endless ore, instant build, arsenal":"усё адкрыта, руда без канца, імгненная будоўля, арсенал",
"Trainings — all 4":"Навучанні — усе 4",
"PC and phone (strategy and shooter)":"ПК і тэлефон (стратэгія і стралок)",
"Cinema: split screen":"Кіно: спліт-экран",
"strategist bot left, shooter bot right":"злева бот-стратэг, справа бот-стралок",
"Cinema: everything built":"Кіно: усё пабудавана",
"both bases built and upgraded — for footage":"абедзве базы адбудаваны і пракачаны — для здымак",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Кіно-рэжым — спліт-экран: злева бот-стратэг (выгляд зверху на базу і армію), справа бот-стралок ад першай асобы. Кнопкі ўнізе (і клавішы S, P): «Спліт-экран» і «★ Усё пабудавана» — абедзве базы адбудаваны і пракачаны для здымак.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Ядра і тунэляў скрозь метэарыт больш няма — метэарыт суцэльны, бой толькі на паверхні.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Тэлефон: 👁 хавае інтэрфейс, але пакідае джэтпак, ⇆, сцікі і маркер задачы. «◎ Прыцэл» (толькі правы палец) — магніт прыкметна мацнейшы і шырэйшы; сіла магніта для трох рэжымаў — Налады → Кіраванне → «Пашыраныя». На гарматы машыны кнопка называецца «Злезці».",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Навучанне: на тэлефоне — толькі тэлефонныя, на ПК — толькі ПК. Усе 4 — у меню «🛠 Распрацоўшчык». Рэжым распрацоўшчыка і Арсенал аб'яднаны ў адно меню (у баі — «🛠 Меню» уверсе справа, на ПК яшчэ F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Стылі графікі «Dendy (8-біт)» і «16-біт»: Налады → Графіка → «Стыль графікі» (дэталі — кнопка ⚙). Калі ў першыя ~10 с матча FPS ніжэй за 24 — Dendy ўключаецца сам (ніжэй за 20 і далей — яшчэ буйнейшы піксель, 120 радкоў); плашка зверху «вярнуць звычайную» вяртае звычайную графіку назаўсёды. Твой выбар у меню заўсёды мае прыярытэт.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D-мадэлі наваколля (руіны, тэхніка, умацаванні) — толькі тыя, што атрымалі добрыя адзнакі; загружаюцца па патрабаванні з інтэрнэту. Выключыць: Налады → Графіка → «Новыя 3D-мадэлі наваколля».",
"New in v7.5":"Новае ў v7.5",
"NEW IN v7.5":"НОВАЕ Ў v7.5",
