"Trooper, the engineers are busy — help finish the {0}, {1} m. {2} at the site.":"Салдат, інжынеры занятыя — дапамажы дабудаваць: {0}, {1} м. {2} каля будоўлі.",
"Strategist order: finish the {0} ({1} m)":"Загад стратэга: дабудаваць {0} ({1} м)",
"Strategist: target mark ⌖ on an enemy cluster, {0} m — artillery in 8 seconds. Stay clear!":"Стратэг: пазнака ⌖ на скопішча ворага, {0} м — артылерыйскі ўдар праз 8 секунд. Не падыходзь!",
"MLRS \"Grad\" ×{0}: salvo at the strategist's mark":"РСЗВ «Град» ×{0}: залп па пазнацы стратэга",
"a heavy MG for 90 s":"цяжкі кулямёт на 90 с",
"incendiary rounds for 60 s":"запальныя патроны на 60 с",
"3 rockets with no cooldown":"3 ракеты без перазарадкі",
"Weapon cache: ":"Тайнік: ",
" · grenades and mags full":" · гранаты і магазіны поўныя",
"⌖ ARTILLERY":"⌖ АРТУДАР",
"STRATEGIST'S MARK":"ПАЗНАКА СТРАТЭГА",
"BUILD SITE":"БУДОЎЛЯ",
"cache":"тайнік",
" m":" м",
