"— stop":"— стоп",
"PRONE · crawling · Ctrl — stand up":"ЛЁЖАЧЫ · поўзма · Ctrl — падняцца",
"stop building":"перастаць будаваць",
"cache: take the weapons":"тайнік: узяць зброю",
"Building: {0} — stay close":"Будуеш: {0} — стой побач",
"Prone / stand up (crawl)":"Лячы / падняцца (поўзма)",
"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Будоўля салдатамі: E (на тэлефоне «Увайсці») каля сваёй будоўлі — салдат будуе сам, напарнікі побач дапамагаюць. Калі інжынеры занятыя, стратэг сам папросіць дапамагчы — пазнака «БУДОЎЛЯ».",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Пазнакі стратэга: стратэг ставіць ⌖ на скопішча ворагаў побач з табой — праз 8 с туды б'е артылерыя, а свае РСЗВ «Град» побач даюць залп. Твой артылерыйскі ўдар са стратэгіі — таксама з падтрымкай «Градаў».",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Тайнікі са зброяй у грузавых кантэйнерах і ўпалых спадарожніках (📦 відаць з 70 м): E — кулямёт на 90 с, запальныя ці ракеты, плюс поўныя гранаты. Поўзма: Ctrl — легчы / падняцца (ніжэй, ціхней, дакладней, але павольна).",
"Anonymous statistics":"Ананімная статыстыка",
"no names or emails: version, device, play time — to make the game better":"без імён і пошты: версія, прылада, час гульні — каб рабіць гульню лепшай",
"Anonymous statistics (no names or emails)":"Ананімная статыстыка (без імён і пошты)",
"Split-screen cinema, no core or tunnels, troopers build, strategist marks, caches, crawling, developer menu":"Кіна-спліт-экран, без ядра і тунэляў, будоўля салдатамі, пазнакі стратэга, тайнікі, поўзма, меню распрацоўшчыка",
"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"Тры рэжымы сцікаў на тэлефоне, простая стратэгія, гармата машыны, рэльеф з каньёнамі, класы атрадаў, выбуховае рэчыва",
"Lite mode, two-stick phone controls":"Лёгкі рэжым, два сцікі на тэлефоне",
"Milestone: outposts and HQ upgrades, cinematic misses, knockdowns":"Вяха: заставы і паляпшэнні штаба, кінавыя промахі, падзенне ад выбухаў",
"Milestone: strategy + shooter in one game, v6 guns":"Вяха: стратэгія + шутэр у адной гульні, зброя v6",
