"Do not like the new version — play the one you are used to. The choice is remembered; every version has its own saves and settings (these stay safe). An old version is loaded only when chosen.":"Не падабаецца новая версія — гуляй у звыклую. Выбар запамінаецца; у кожнай версіі свае захаванні і налады (гэтыя не прападуць). Старая версія загружаецца толькі пры выбары.",
