"from blasts and hits, gentle":"ад выбухаў і ўдараў, мяккае",
"last enemy nearby, tank, HQ":"апошні вораг побач, танк, штаб",
"corner; F7 — collapse":"у кутку; F7 — згарнуць",
"Link copied":"Спасылка скапіравана",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"«▶ Іграць зараз» — першая кнопка меню: кароткі праліт пад небам-порталам — і адразу ў бой (прапуск — любая клавіша ці тап).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Трапленні адчуваюцца: металічны гук і іскры, пазнака забойства ля прыцэла (у галаву — жоўтая), серыя ×N, плыўнае трасенне ад выбухаў, слоў-мо на важных забойствах. Трасенне, слоў-мо і падказку можна выключыць у Наладах.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Вынік матча: час, знішчэнні, лепшая серыя, ★ MVP і лепшы атрад, картка матча — «⇪ Падзяліцца», PNG ці спасылка на гульню.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Падказка «што рабіць зараз» злева пад рэсурсамі: загад стратэга, кропка для захопу, наступленне Роя. ✕ ці F7 — згарнуць.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Бой захоўваецца сам, калі закрыць ці згарнуць укладку, — у меню «⟲ Працягнуць».",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Версія v7.5 засталася ў меню «🕘 Версія гульні» — калі новая не спадабаецца. Ананімная статыстыка (без імён і пошты) цяпер адпраўляецца; выключыць — у Наладах.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"«Іграць зараз», водгук трапленняў, вынік матча з карткай, падказка «што рабіць», аўтазахаванне",
"and older: v7.5, v7.4, milestones v1–v7.0":"і старыя: v7.5, v7.4, вехі v1–v7.0",
"New in v7.6":"Новае ў v7.6",
"NEW IN v7.6":"НОВАЕ Ў v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Выбар фракцыі перад матчам: «Кансорцыум» (цяжкая пяхота ў сілавой браніі, браня і артылерыя) ці «Рой» (хуткасць, зграі дронаў, цяжкія стрэлы са скажэннем). ШІ гуляе за іншую. Выбар запамінаецца.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"У кожнай фракцыі свая тэхніка і ўнікальныя юніты: у Кансорцыума — танк «Насарог» і «Керамітавыя пліты», у Роя — «Зграя дронаў» і «Фазавыя ранцы». Баланс правераны матчамі з ботамі.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Варонкі ад выбухаў: артылерыя, ракеты і танкавыя гарматы выбіваюць у метэарыце ямы — праз іх можна хадзіць і ездзіць, у іх можна хавацца.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Выгляд ад трэцяй асобы для салдат (V, запамінаецца; на тэлефоне — «Кіраванне») і плаўная камера тэхнікі з меткай, куды трапіць снарад.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Версія v7.6 засталася ў меню «🕘 Версія гульні» — на выпадак, калі яна вам больш даспадобы.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Фракцыі «Кансорцыум» / «Рой» з выбарам перад матчам, варонкі ад выбухаў, выгляд ад трэцяй асобы",
