"The Commander mode is not in the game yet":"Рэжыму «Камандзір» у гульні яшчэ няма",
"Commander · soon":"Камандзір · хутка",
"Commander — still in development":"Камандзір — яшчэ ў распрацоўцы",
"Pause: resume, restart, training, graphics, settings, main menu":"Паўза: працягнуць, зноў, навучанне, графіка, налады, галоўнае меню",
"Menu: pause, restart, training, graphics, settings":"Меню: паўза, зноў, навучанне, графіка, налады",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Трымай палец на зямлі ~0,3 с — тэлефон здрыганецца і з'явіцца жоўтае кольца — і, не адпускаючы, вядзі: атрымаецца рамка. Або кнопка «Рамка» справа. Можна і проста тапнуць па атрадзе.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Для поўнага экрана на iPhone: «Падзяліцца» ⬆ → «На экран «Дадому»» — гульня адкрыецца без панэляў Safari.",
"Open portal-meteor.pages.dev for that.":"Адкрый для гэтага сайт portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Тап — вылучыць · тап па зямлі — ісці · трымай — меню загадаў · трымай і вядзі — рамка · 2 пальцы — маштаб",
"Robo-ninja":"Робаніндзя",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Гераіня-забойца: рыўкі-тэлепарты, катана, шурыкены. Сама скача па зонах ворага і рэжа робатаў. 1 на бок.",
"Shadow protocol":"Пратакол «Цень»",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Даследаванне: адчыняе робаніндзя ў Казармах. Патрэбны гатовы завод мехаў.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Гераіня (1 на бок): сама тэлепартуецца па зонах ворага і рэжа робатаў; можна захапіць яе і гуляць уручную.",
"is ready. She works on her own (AUTO) — possess her to play manually":"гатова. Працуе сама (АЎТА) — захапі яе, каб гуляць уручную",
"Robo-ninja ready for action":"Робаніндзя гатова да бою",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Разведка: у праціўніка з'явілася робаніндзя!",
"Warning! The enemy has a robo-ninja. Stay together":"Увага! У праціўніка робаніндзя. Трымайцеся разам",
"cyber blinks":"кібер-рыўкі",
"Too far for a dash — get closer or teleport":"Далёка для рыўка — падбяжы бліжэй або тэлепарт",
