"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ ДУЭЛЬ НІНДЗЯ! Блок перад ударам — парыраванне, рывок — ухіленне. Сачы за ўспышкай замаху",
"The two ninjas have met in a duel!":"Дзве ніндзя сышліся ў дуэлі!",
"⚔ Duel won! Our ninja prevails":"⚔ Дуэль выйграна! Наша ніндзя мацнейшая",
"⚔ Duel lost…":"⚔ Дуэль прайграна…",
"ninja duel":"дуэль ніндзя",
"POSTURE BROKEN":"СТОЙКА ЗЛАМАНА",
"Teleport":"Тэлепарт",
"Teleport: aim at the ground (up to 150 m)":"Тэлепарт: навядзі прыцэл на зямлю (да 150 м)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ АЎТА: сама скача па зонах ворага і рэжа. Джойсцік / WASD — паўза 1.5 с",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Ручное: тап па ворагу — рывок і ўдар, свайп — узмах, 🛡 — блок",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Ручное кіраванне: ЛКМ — катана, ПКМ — блок, Shift — рывок, Q — шурыкены, G — тэлепарт",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ніндзя: тап па ворагу — рывок і ўдар, свайп справа — узмах, ● — удар, 🛡 — блок (своечасова = парыраванне), ⇑ — рывок, ✦ — шурыкены, ◎ — тэлепарт, АЎТА — сама",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ніндзя: ЛКМ — катана (трымаць — цяжкі ўдар), ПКМ — блок (своечасова = парыраванне), Shift/Z — рывок, Q — шурыкены, G — тэлепарт да прыцэла, скачок у паветры — двайны / бег па сцяне, {0} — АЎТА",
