"Disabled":"Выключана",
"Requires a finished Mech factory":"Патрэбны гатовы завод мехаў",
"Requires \"Shadow protocol\" research":"Патрэбна даследаванне «Пратакол „Цень“»",
"Hero already deployed (1 per side)":"Гераіня ўжо ёсць (1 на бок)",
"Research complete: Shadow protocol — the robo-ninja is available in the Barracks":"Даследаванне завершана: Пратакол «Цень» — у Казарме даступная робаніндзя",
"Shadow protocol ready. The robo-ninja can be deployed":"Пратакол «Цень» гатовы. Можна выклікаць робаніндзя",
"✶ Our robo-ninja is down. Deploy her again in the Barracks":"✶ Наша робаніндзя знішчана. Можна выклікаць зноў у Казарме",
