"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Радыё Portal Meteor: 100+ трэкаў EDMITRY проста ў гульні — кнопка 📻 (ПК: клавіша 5, [ ] — трэк). Музыка падгружаецца па сетцы і не абцяжарвае гульню; гучнасць і аўтазапуск у наладах, плюс спасылка «Слухаць у Spotify».",
"tuning…":"налада…",
"on air · cockpit":"эфір · кабіна",
"on air":"у эфіры",
"paused":"паўза",
"no signal — silent":"няма сувязі — ціха",
"tap ▶":"націсні ▶",
"RADIO PORTAL METEOR":"РАДЫЁ PORTAL METEOR",
"Now playing":"Зараз іграе",
"Listen on Spotify":"Слухаць у Spotify",
"RADIO":"РАДЫЁ",
"on/off":"укл",
"track":"трэк",
"Radio":"Радыё",
"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"Радыё Portal Meteor укл/выкл ([ ] — трэк, Shift+[ ] — гучнасць)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 справа — Радыё Portal Meteor: музыка EDMITRY падчас бою.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Радыё Portal Meteor: музыка EDMITRY падчас бою. [ ] — трэк.",
"Radio Portal Meteor (EDMITRY): volume":"Радыё Portal Meteor (EDMITRY): гучнасць",
"Radio: start by itself in battle":"Радыё: уключаць само ў баі",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Робаніндзя: кіберг з катанай. Адкрываецца ў Казарме даследаваннем «Пратакол „Цень“» (патрэбны завод мехаў). Сама тэлепартуецца ў зоны ворага, рэжа ворагаў на часткі (без крыві — іскры), рыўкі, шурыкены, дуэлі з варожым ніндзя. Захапі яе — рэжым АЎТА або ручное кіраванне (на тэлефоне — свае кнопкі).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Радыё Portal Meteor: 103 трэкі EDMITRY проста ў гульні. Клавіша 5 (перапрызначаецца), на тэлефоне — ☰ → Налады → Гук. Гучнасць і «уключаць само ў баі» — у наладах; музыка цішэйшая на выбухах і пад голас рацыі.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Новыя мовы: узбекская і таджыкская — цалкам; кітайская, іспанская, партугальская — часткова. Новы выбар мовы ў меню побач з «Новы матч».",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Тэлефон: «схаваць значкі» 👁 збірае астатнія кнопкі ў акуратную калонку ля правага краю; партрэт больш не налазіць; iPhone — гульня не канфліктуе з жэстамі Safari, а «Падзяліцца → На экран „Дадому“» запускае яе на ўвесь экран.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"З v7.8.1: меню ☰ у куце (паўза, нанова, навучанне, графіка), без аўта-Dendy, кнопка дзеяння ✋ на тэлефоне. v7.8.1 і v7.8 засталіся ў меню «🕘 Версія гульні».",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Робаніндзя, радыё EDMITRY, узбекская і таджыкская, зручнасць тэлефона і iPhone",
