"Medium":"Сярэдняя",
"High":"Высокая",
"Ultra":"Ультра",
"Still slow on “Low”? Try the Dendy mode — it is lighter":"Тармозіць нават на «Нізкай»? Паспрабуй рэжым Dendy — ён лягчэйшы",
