"♨ AIR RAID! Swarm napalm — get out of the red circle!":"♨ ПАВЕТРАНАЯ ТРЫВОГА! Напалм Роя — сыходзь з чырвонага круга!",
"Air raid! Bomber overhead!":"Паветраная трывога! Бамбардзіроўшчык над нами!",
"Carpet bombing":"Дывановае бамбаванне",
"A bomber drops 10 bombs along an 80 m strip, approaching from your base (in battle — along your view). After 3.5 s, leaves craters.":"Бамбардзіроўшчык скідвае 10 бомбаў паласой 80 м, заходзячы ад вашай базы (у баі — уздоўж погляду). Праз 3,5 с; пакідае варонкі.",
"Napalm":"Напалм",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"Зона агню радыусам 12 м гарыць 9 секунд: урон з часам, прыгнёт, дым. Праз 2,5 с. Падпальвае метан.",
"Bomber: target received, inbound!":"Бамбардзіроўшчык: мэта прынята, заходзім!",
"Attack jet: napalm inbound!":"Штурмавік: напалм на падыходзе!",
"Support: crate, recon, \"Grad\", artillery, carpet bombing, napalm (then 1–6)":"Падтрымка: скрыня, разведка, «Град», артылерыйскі ўдар, бамбаванне, напалм (потым 1–6)",
"☄ Meteor shower in 10 s — take cover: the rock hangar, under a ridge!":"☄ Метэарытны дождж праз 10 с — у сховішча: ангар у скалах, пад грэбень!",
"Warning: meteor shower! Everyone take cover":"Увага: метэарытны дождж! Усім у сховішча",
