" s — take cover":" с — у сховішча",
"Concrete barrier":"Бетонны бар'ер",
"Consortium. 7 m wall section: stops bullets, shells and vehicles. Chain them (Shift+click).":"Кансорцыум. Секцыя сцяны 7 м: трымае кулі, снарады і тэхніку. Стаў ланцужком (Shift+клік).",
"Repair post":"Рамонтны пост",
"Consortium. Repairs vehicles, buildings and infantry within 26 m.":"Кансорцыум. Рамантуе тэхніку, будынкі і пяхоту ў радыусе 26 м.",
"Tunnel burrow":"Тунэльная нара",
