"Tunnel open! Select squads → \"Into tunnel\" on the card or RMB the burrow":"Тунэль прарыты! Вылучы атрады → «У тунэль» у карце або ПКМ па нары",
"The tunnel is through. Ready to move":"Тунэль прарыты. Можна пераходзіць",
"⚠ The Swarm broke through from underground! Destroy the \"Tunnel exit\"":"⚠ Рой прарваўся з-пад зямлі! Знішчы «Выхад тунэля»",
"The tunnel collapsed":"Тунэль абрынуўся",
