"⚠ Rumbling underground: the Swarm is digging a tunnel! Breakthrough in ~10 s — be ready":"⚠ Гул пад зямлёй: Рой рые тунэль! Прарыў праз ~10 с — сустракай",
"Warning! Digging heard. The enemy is tunnelling":"Увага! Чуем падкоп. Праціўнік рые тунэль",
"Needs a Tunnel burrow — builders make it":"Патрэбна Тунэльная нара — яе будуюць інжынеры",
