"Tap the exit point (up to {0} m from the burrow)":"Тапні кропку выхаду (да {0} м ад нары)",
"LMB — exit point (up to {0} m from the burrow), RMB — cancel":"ЛКМ — кропка выхаду (да {0} м ад нары), ПКМ — адмена",
"Dig the exit first":"Спачатку прарый выхад",
"Into the tunnel: {0} squad(s)":"У тунэль: атрадаў {0}",
"no squads within 70 m of the burrow — select squads and RMB/tap the burrow":"побач з нарой (70 м) атрадаў няма — вылучы атрады і ПКМ/тап па нары",
"Digging: {0} s. The enemy will hear it 10 s before breakthrough":"Рыем тунэль: {0} с. Вораг пачуе гул за 10 с да прарыву",
"Exit · {0} m · {1} s":"Выхад · {0} м · {1} с",
"Dig the exit":"Прарыць выхад",
"Swarm. Pick a point up to 220 m away — the exit breaks through in 24 s. 10 s before, the enemy hears rumbling and sees dust.":"Рой. Абяры кропку да 220 м — выхад прарвецца праз 24 с. За 10 с да прарыву вораг пачуе гул і ўбачыць пыл.",
"Squads into the tunnel":"Атрады — у тунэль",
"Swarm. Squads within 70 m of the burrow (and selected ones) go through the tunnel. Or select squads and RMB/tap the burrow.":"Рой. Атрады ў 70 м ад нары (і вылучаныя) ідуць у тунэль і выходзяць на другім канцы. Або: вылучы атрады і ПКМ/тап па нары.",
"Swarm only":"Толькі ў фракцыі «Рой»",
