"Consortium. From 12:00. Builds the super-heavy tank \"Bastion\" (one per army).":"Кансорцыум. З 12:00 бою. Тут збіраюць звыхцяжкі танк «Бастыён» (адзін на армію).",
"Incubator":"Інкубатар",
"Swarm. From 12:00. Grows the \"Reaper\" walker (one per army).":"Рой. З 12:00 бою. Тут расце шагаход «Жнец» (адзін на армію).",
"Super-heavy tank \"Bastion\"":"Звыхцяжкі танк «Бастыён»",
"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Кансорцыум. Бос: 15000 трываласці, гармата, 2 кулямёты, ракеты. Вельмі павольны. Слабое месца — задняя частка. Адзін на армію.",
"Walker \"Reaper\"":"Шагаход «Жнец»",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Рой. Бос: 12500 трываласці, прамень скажэння, тупат. Пераступае бар'еры. Слабое месца — ядро пад брухам. Адзін на армію.",
"Limit: 1 per army":"Ліміт: 1 на армію",
