"⚠ WARNING: the enemy is assembling the {0}!":"⚠ УВАГА: праціўнік збірае {0}!",
"Warning! The enemy is assembling the {0}. Find and destroy the plant before it is too late.":"Увага! Праціўнік збірае {0}. Знайдзіце і знішчыце цэх, пакуль не позна.",
"⚠ WARNING: the enemy {0} is on the battlefield!":"⚠ УВАГА: {0} праціўніка выйшаў на поле бою!",
"Warning! The enemy {0} is on the field!":"Увага! {0} праціўніка на полі бою!",
"Weak spot! Nearly double damage":"Слабае месца! Страта амаль удвая большая",
"Our {0} is destroyed!":"Наш {0} знішчаны!",
