"ours":"наш",
"key":"клавіша",
"Strip: ⟳ to rotate, or drag from the target along the run":"Паласа: ⟳ — павярнуць, або правядзі пальцам ад мэты ў бок заходу",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"Паласа: кола мышы або R — павярнуць, або правядзі мышшу ад мэты ў бок заходу",
"Into the tunnel: {0} vehicle(s)":"У тунэль: тэхнікі {0}",
"Light and medium vehicles go into the nearest open tunnel":"Лёгкая і сярэдняя тэхніка ідзе ў бліжэйшы адкрыты тунэль",
"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Рой. Атрады ў 70 м ад нары (і вылучаныя), а таксама вылучаная лёгкая/сярэдняя тэхніка («Шакал», «Молат», «Град») ідуць праз тунэль і выходзяць на іншым канцы. Або: вылучы і ПКМ/тап па нары.",
"Air strikes":"Паветраныя ўдары",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"Дыванная бамбардзіроўка і напалм: прыцэл, паварот паласы, папярэджанне ворага, выклік з бою",
"Terrain and lakes":"Рэльеф і азёры",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"Лава паліць, лёд коўзкі, метан выбухае ад агню, ангар у скалах — сховішча",
"Swarm: tunnels":"Рой: тунэлі",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"Ты гуляеш за Рой: Тунэльная нара, выхад да 220 м, пыл-папярэджанне, атрады і тэхніка — у тунэль",
"Consortium: fortifications":"Кансорцыум: умацаванні",
"You play the Consortium: barrier chains, repair post, field repair by builders":"Ты гуляеш за Кансорцыум: бетонныя бар'еры ланцужком, Рамонтны пост, палявы рамонт інжынерамі",
"Bosses":"Босы",
"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"«Бастыён» і «Жнец»: з 12:00 (на ўроку — перамотка), цэх, зборка, загад, слабыя месцы, захоп",
"ENEMY STRIKE":"УДАР ВОРАГА",
