"GENERATOR":"ГЕНЕРАТАР",
"RELAY":"РЭТРАНСЛЯТАР",
"SABOTAGE":"ДЫВЕРСІЯ",
"Living world: requests, hero quests, breakthrough ops":"Жывы свет: просьбы сваіх, квэсты герояў, пералом баю",
"Living world":"Жывы свет",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Свае просяць дапамогі і ўзнагароджваюць, героі даюць квэсты, зацяжны фронт ламаюць аперацыяй",
"A request":"Просьба сваіх",
"Breakthrough":"Пералом баю",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Свае іншы раз просяць дапамогі: голас па радыё, картка «ПРАСЬБА» і маркер ✋. Атрад прыціснулі — знішчы ворагаў каля яго. Узнагарода: баец капсулай з базы, ствол з кузава багі, месца стралка або прыкрыццё з арбіты. Не хочаш — ✕ або проста ігнаруй.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Ветэран-разведчык «Сыч» прапануе квэст. Y — прыняць (N — адмова). Ідзі да пазнакі ★, здымі ахову і пастой ля пілота 3 с — ён стане ў твой атрад.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Фронт спыніўся — штаб прапануе пералом. Y — прыняць. Трымай рэтранслятар 8 с без ворагаў побач: карта ворага бачная 60 с. Генератар — турэлі ворага маўчаць 2 хв. У рэжыме «Стратэг» — «Выдаць атраду». Вораг таксама так умее: сачы за ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Свае просяць дапамогі: картка «ПРАСЬБА» і маркер ✋. Знішчы ворагаў каля прыціснутага атрада — атрымаеш узнагароду. ✕ — прапусціць.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Герой «Сыч» прапануе квэст — тапні «Прыняць». Ідзі да ★, здымі ахову, пастой ля пілота.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Фронт спыніўся — тапні «Прыняць» і трымай рэтранслятар 8 с: карта ворага адкрыецца на хвіліну.",
"Pod redeploy from the base: {0} m — through the sky portal":"Перакідка капсулай з базы: {0} м — праз неба-партал",
"Pod away from the base! Hold on — exit over the target.":"Капсула пайшла з базы! Трымайцеся — выхад над мэтай.",
"Landed at the objective!":"Высадка ля мэты!",
"LAUNCH FROM BASE":"ПУСК З БАЗЫ",
"LANDING":"ПАСАДКА",
"REDEPLOY":"ПЕРАКІДКА",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Сталёвы пух прыліп — раз'ядае браню −2/с. Пастой 3 с па-за боем або знайдзі інжынера",
"An engineer brushed the fluff off":"Інжынер ачысціў Сталёвы пух",
"The fluff fell off — armour is safe":"Сталёвы пух асыпаўся — браня цэлая",
"The firefly swarm scattered by the blast":"Рой светлякоў разагнаны выбухам",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"СТАЛЁВЫ ПУХ −2/с · стой 3 с па-за боем або да інжынера",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Канвой «Леўшы» гатовы: два «Шакалы». Трымайся побач — без цябе чакаюць",
"The convoy is waiting for you":"Канвой чакае цябе",
"Ambush! Cover the Jackals!":"Засада! Прыкрый «Шакалаў»!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"канвой дайшоў ({0} з 2)! +2 ВК, +150 руды, «Шакалы» твае",
"The parts are delivered! Thanks, commander.":"Дэталі на месцы! Дзякуй, камандзір.",
"Show tips again":"Паказаць падказкі нанова",
"Reset":"Скінуць",
"Sure? Tap again":"Дакладна? Яшчэ раз",
"Done":"Гатова",
"Tips and lessons will show again":"Падказкі і ўрокі пакажуцца нанова",
"Steel fluff":"Сталёвы пух",
"Rootwalker":"Рушнік",
"Firefly swarm":"Рой светлякоў",
"Steel dandelions — Steel fluff! It sticks and eats armour!":"Сталёвыя дзьмухаўцы — Сталёвы пух! Прыліпне — праесць браню!",
"Fluff in the air — keep out of the meadow and away from the infected!":"Пух ляціць — не лезь на паляну і не церся аб заражаных!",
"fluff blown away, dormant for 25 s · +0.5 CP":"Сталёвы пух здзьмуты, паляна спіць 25 с · +0.5 ВК",
"My crew is hauling parts to point {0}. Escort the column — there may be an ambush.":"Мае хлопцы вязуць дэталі на кропку {0}. Правядзі калону — па дарозе могуць чакаць.",
"Escort the convoy to point {0}":"Суправадзіць канвой да кропкі {0}",
